    }

    .dark .monday-search .ant-input-affix-wrapper-focused,
    .dark .monday-search .ant-input-affix-wrapper:focus-within {
      border-color: #4da6ff !important;
      box-shadow:
        0 0 0 4px rgba(77, 166, 255, 0.15),
