      border-radius: 8px !important;
      margin: 2px 0 !important;
      padding: 2px !important;
      border: 1px solid rgba(0, 115, 234, 0.25) !important;
      box-shadow:
        0 2px 12px rgba(0, 115, 234, 0.1),
        0 1px 4px rgba(0, 115, 234, 0.08),
        inset 0 1px 0 rgba(255, 255, 255, 0.1) !important;
      position: relative !important;
      z-index: 5 !important;
    }

    .dark .ant-tree-treenode.drag-highlight {
      background: linear-gradient(135deg, rgba(77, 166, 255, 0.1) 0%, rgba(77, 166, 255, 0.05) 100%) !important;
      border: 1px solid rgba(77, 166, 255, 0.3) !important;
      box-shadow:
        0 2px 12px rgba(77, 166, 255, 0.12),
        0 1px 4px rgba(77, 166, 255, 0.1),
        inset 0 1px 0 rgba(255, 255, 255, 0.03) !important;
    }

    /* Add a subtle pulse animation to the highlighted row */
    .ant-tree-treenode.drag-highlight::before {
