      border-radius: 8px;
      animation: rowHighlightPulse 2s ease-in-out infinite;
      pointer-events: none;
      z-index: -1;
    }

    .dark .ant-tree-treenode.drag-highlight::before {
      background: linear-gradient(45deg,
