      bottom: -2px;
      background: linear-gradient(45deg,
        rgba(0, 115, 234, 0.1) 0%,
        rgba(0, 115, 234, 0.05) 25%,
        rgba(0, 115, 234, 0.1) 50%,
        rgba(0, 115, 234, 0.05) 75%,
        rgba(0, 115, 234, 0.1) 100%);
      border-radius: 8px;
      animation: dragOverPulse 1.5s ease-in-out infinite;
      pointer-events: none;
      z-index: -1;
    }

    .dark .ant-tree-node-content-wrapper.bg-primary/10::before {
      background: linear-gradient(45deg,
        rgba(77, 166, 255, 0.12) 0%,
        rgba(77, 166, 255, 0.06) 25%,
        rgba(77, 166, 255, 0.12) 50%,
        rgba(77, 166, 255, 0.06) 75%,
        rgba(77, 166, 255, 0.12) 100%);
    }

    @keyframes dragOverPulse {
      0%, 100% {
        opacity: 0.6;
        transform: scale(1);
      }
      50% {
        opacity: 1;
        transform: scale(1.01);
      }
    }

    /* Drag cursor styling */
    .ant-tree-node-content-wrapper[data-is-kb="true"]:hover,
    .ant-tree-node-content-wrapper[data-is-folder="true"]:hover {
      cursor: copy;
    }

    .ant-tree-node-content-wrapper[data-has-file-management="false"][data-has-write="false"]:hover {
      cursor: not-allowed;
