    text-decoration: none;
  }

  .toastui-editor-contents a[href^="#"]:hover {
    text-decoration: underline;
  }

  /* Limit width of tables and add horizontal scroll if needed */
  .toastui-editor-contents table {
    max-width: 100%;
    display: block;
    overflow-x: auto;
    white-space: nowrap;
  }

  .toastui-editor-contents table th,
